    // never Exact, never a drop, never the stem heuristic.
    assert_eq!(
        cg.methods
            .get(&("Missing".to_string(), "make".to_string()))
            .map(|v| v.len()),
        Some(2),
        "the bare owner key must collide so the floor is a NameOnly demote, not Exact",
