        out.resolved
            .iter()
            .all(|c| c.confidence == ResolutionConfidence::NameOnly),
        "fail-open lands at the #120 NameOnly demote floor"
    );
    assert!(
        out.resolved
            .iter()
            .all(|c| c.kind == ResolutionKind::QualifiedOwner),
