fn graph_owner_name_for_scope(graph: &ScopeGraph, scope: ScopeId) -> Option<String> {
    graph
        .bindings
        .iter()
        .find_map(|binding| match &binding.target {
            BindTarget::Resolved(Target::Item {
                owns: Some(owner), ..
            }) if *owner == scope => Some(binding.name.clone()),
            _ => None,
        })
}

